import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { chmodSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { test } from 'node:test';
import { fileURLToPath } from 'node:url';
import { publish, withBlock } from './pr-description-block.mjs';

const SCRIPT = fileURLToPath(new URL('./pr-description-block.mjs', import.meta.url));

const NOTE = '<!-- Generated on every push by the token-budget workflow; do not edit. -->';
const PREVIEW_NOTE = '<!-- Generated by the preview workflows; do not edit. -->';
const tb = (body, report) => withBlock(body, 'token-budget', report);
const pv = (body, content) => withBlock(body, 'preview', content);

const TB = (r) => `<!-- token-budget -->\n${NOTE}\n${r}\n<!-- /token-budget -->`;
const PV = (c) => `<!-- preview -->\n${PREVIEW_NOTE}\n${c}\n<!-- /preview -->`;

test('without a block, it goes at the end of the description', () => {
  assert.equal(tb('## ELI5\n\nShort.\n\n## What changed\n\n- a\n', '| total | 1 |\n'), `## ELI5\n\nShort.\n\n## What changed\n\n- a\n\n${TB('| total | 1 |')}\n`);
  assert.equal(tb('## Why\nx\n\n', 'r'), `## Why\nx\n\n${TB('r')}\n`);
  assert.equal(tb('', 'r'), `${TB('r')}\n`);
});

test('an existing block is replaced in place and the text around it stays', () => {
  const body = `## ELI5\n\nShort.\n\n${TB('old')}\n\n## What changed\nkept`;
  assert.equal(tb(body, 'new\n'), `## ELI5\n\nShort.\n\n${TB('new')}\n\n## What changed\nkept`);
});

test('markers named inside a line are text, not a block', () => {
  const body = 'The `<!-- token-budget -->` and `<!-- /token-budget -->` lines.\n';
  assert.equal(tb(body, 'r'), `${body}\n${TB('r')}\n`);
});

test('a CRLF body gets a CRLF block', () => {
  assert.equal(tb('## ELI5\r\n\r\nShort.', 'a\nb\n'), `## ELI5\r\n\r\nShort.\r\n\r\n${TB('a\nb').replaceAll('\n', '\r\n')}\r\n`);
});

test('an opening marker quoted alone in a fence is text, also on the next run', () => {
  const body = 'Intro\n```\n<!-- token-budget -->\n```\n## Next\nx\n';
  const first = tb(body, 'r1');
  assert.equal(first, `${body}\n${TB('r1')}\n`);
  assert.equal(tb(first, 'r2'), first.replace('r1', 'r2'));
});

test('a whole example block quoted in a fence is text', () => {
  const example = `~~~md\n${TB('example')}\n~~~\n`;
  assert.equal(tb(`## Docs\n${example}`, 'r'), `## Docs\n${example}\n${TB('r')}\n`);
});

test('a fence open to the end is closed before the appended block, which the next run replaces', () => {
  const first = tb('Intro\n````js\nexample\n', 'r1');
  assert.equal(first, `Intro\n\`\`\`\`js\nexample\n\`\`\`\`\n\n${TB('r1')}\n`);
  assert.equal(tb(first, 'r2'), first.replace('r1', 'r2'));
  assert.equal(tb('Intro\n~~~', 'r'), `Intro\n~~~\n~~~\n\n${TB('r')}\n`);
});

test('the preview block goes after a token budget block at the end', () => {
  const body = `## Why\nx\n\n${TB('r')}\n`;
  assert.equal(pv(body, 'link'), `${body}\n${PV('link')}\n`);
});

test('the token budget block goes before a preview block at the end, so both new blocks keep their order', () => {
  const both = `## Why\nx\n\n${TB('r1')}\n\n${PV('link')}\n`;
  assert.equal(tb(pv('## Why\nx\n', 'link'), 'r1'), both);
  assert.equal(pv(tb('## Why\nx\n', 'r1'), 'link'), both);
  assert.equal(pv(tb(both, 'r2'), 'removed'), both.replace('r1', 'r2').replace('link', 'removed'));
});

test('a preview block followed by text keeps its place, and the token budget block goes at the end', () => {
  const body = `${PV('link')}\n\n## Why\nx\n`;
  assert.equal(tb(body, 'r'), `${body}\n${TB('r')}\n`);
});

test('fenced code at the end is text: a quoted preview block is no block and ends the description', () => {
  const body = `## Why\n${TB('r')}\n\`\`\`\n${PV('old')}\n\`\`\`\n`;
  assert.equal(pv(body, 'new'), `${body}\n${PV('new')}\n`);
  // Fenced code after a preview block ends the description, so the token budget block goes after the fence.
  const fenced = `## Why\n${PV('link')}\n\`\`\`\nquoted\n\`\`\`\n`;
  assert.equal(tb(fenced, 'r'), `${fenced}\n${TB('r')}\n`);
});

test('an unknown block name throws', () => {
  assert.throws(() => withBlock('', 'other', 'x'), /unknown block "other"/);
});

test('a concurrent overwrite that drops the block gets one more write', async () => {
  let stored = '## ELI5\nShort.\n';
  const stale = stored;
  const writes = [];
  const tries = await publish({
    read: () => stored,
    write: (body) => {
      writes.push(body);
      // The other workflow wrote the body it read before this write, with its own block.
      stored = writes.length === 1 ? tb(stale, 'r') : body;
    },
    name: 'preview',
    content: 'link',
  });
  assert.equal(tries, 2);
  assert.equal(stored, `## ELI5\nShort.\n\n${TB('r')}\n\n${PV('link')}\n`);
});

test('a block still missing after three writes fails', async () => {
  await assert.rejects(
    publish({ read: () => '## ELI5\n', write: () => {}, name: 'token-budget', content: 'r' }),
    { message: 'the token-budget block is still missing or stale after 3 writes: another writer keeps replacing the description' },
  );
});

test('the command line writes the block through gh, and prints the usage without its arguments', () => {
  const dir = mkdtempSync(join(tmpdir(), 'pr-description-block-'));
  try {
    // A stand-in gh: `pr view` prints the stored body as JSON, `pr edit --body-file -` stores standard input.
    const store = join(dir, 'body.md');
    writeFileSync(store, '## What changed\n- a');
    writeFileSync(
      join(dir, 'gh'),
      `#!${process.execPath}\nconst fs = require('node:fs');\nconst store = ${JSON.stringify(store)};\nif (process.argv[3] === 'view') process.stdout.write(JSON.stringify({ body: fs.readFileSync(store, 'utf8') }));\nelse fs.writeFileSync(store, fs.readFileSync(0, 'utf8'));\n`,
    );
    chmodSync(join(dir, 'gh'), 0o755);
    writeFileSync(join(dir, 'report.md'), 'r\n');
    const run = (...args) => spawnSync(process.execPath, [SCRIPT, ...args], { encoding: 'utf8', env: { ...process.env, PATH: `${dir}:${process.env.PATH}` } });
    const ok = run('owner/repo', '7', 'token-budget', join(dir, 'report.md'));
    assert.equal(ok.status, 0);
    assert.equal(readFileSync(store, 'utf8'), `## What changed\n- a\n\n${TB('r')}\n`);
    const usage = run('owner/repo', '7', 'other', join(dir, 'report.md'));
    assert.equal(usage.status, 2);
    assert.equal(usage.stderr, 'usage: node .github/scripts/pr-description-block.mjs <owner/repo> <pr-number> <block-name> <content.md>\n');
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});
